std::size_t position(const CommonStore&c,const SourceRef&r){const auto*h=c.state().facts.find(r.id);if(!h||h->domain!=r.domain||h->kind!=r.kind||h->id!=r.id)reject("ContactInquiryOriginalHeaderMissing",r.id);return take(read_actual_common_fact_position(c,*h));}
S3EventRole role(S3ContactInquiryTable t){if(t==S3ContactInquiryTable::started)return S3EventRole::started;if(t==S3ContactInquiryTable::finished)return S3EventRole::finished;reject("ContactInquiryEventTableMismatch");}
const char*kind(S3ContactInquiryTable t){if(t==S3ContactInquiryTable::started)return contact_inquiry_started_kind;if(t==S3ContactInquiryTable::finished)return contact_inquiry_finished_kind;reject("ContactInquiryEventTableMismatch");}
S3ContactInquiryTable table(const SourceRef&r){if(r.domain!=contact_inquiry_module)reject("ContactInquiryEventOwnerMismatch",r.id);if(r.kind==contact_inquiry_started_kind)return S3ContactInquiryTable::started;if(r.kind==contact_inquiry_finished_kind)return S3ContactInquiryTable::finished;reject("ContactInquiryEventKindMismatch",r.id);}
const S3EventTime&event(const ContactInquiryState&s,S3ContactInquiryTable t,const StableId&id){const auto*e=s.temporal_events.find(S3EventTimeKey(t,id,role(t)).value());if(!e||!same_s3_event_record(e->original_record_ref,t,id)||e->event_role!=role(t))reject("ContactInquiryEventTimeMissing",id);take(validate_s3_event_time_shape(*e));return *e;}
const S3ExactEventMoment&moment(const ContactInquiryState&s,S3ContactInquiryTable t,const StableId&id){return *take(read_s3_exact_event(event(s,t,id)));}
const ContactInquiryStarted*start(const ContactInquiryState&s,const StableId&action){const ContactInquiryStarted*out=nullptr;for(const auto&row:s.started.rows())if(row.second.action_id==action){if(out)reject("DuplicateContactInquiryAction",action);out=&row.second;}return out;}
const ContactInquiryFinished*finish(const ContactInquiryState&s,const StableId&action){const ContactInquiryFinished*out=nullptr;for(const auto&row:s.finished.rows())if(row.second.action_id==action){if(out)reject("DuplicateContactInquiryCompletion",action);out=&row.second;}return out;}
const ContactInquiryPolicy&policy(const ContactInquiryTime2Context&x,const ContactInquiryStarted&s){const auto*p=contact_inquiry_policy(x.catalog,s.policy_id);if(!p)reject("ContactInquiryPolicyMissing",s.fact_id);return *p;}
