 const FixedServiceTransition*first=nullptr;const FixedServiceTransition*last=nullptr;std::size_t count=0;for(const auto&v:rows)if(v.action_ref==p.action_ref){++count;if(v.kind==FixedTransitionKind::started&&!first)first=&v;else if(v.kind==FixedTransitionKind::terminal&&!last)last=&v;else reject("ContactInquiryUnexpectedServiceTransition",p.action_ref);if(v.execution_source_schema!=2||!same(v.execution_source_ref,actual.original_execution_source))reject("ContactInquiryServiceOwnerMismatch",p.action_ref);}
