Status ContactInquiryActionTimeRead::validate_shared_action_sources(const ActionTimeRegistration&,const ActionTimeOwnerProof&,const SharedWorkElapsedState&)const{return common_failure("ContactInquiryIsFixedService",{},ErrorKind::internal);}
Outcome<RunStop> ContactInquiryActionTimeRead::read_action_continuation_stop(
    const ActionTimeRegistration &r, const ActionTimeOwnerProof &p,
    const WorldMoment &) const {
  return guard<RunStop>([&] {
    auto actual = take(read_action_time_owner(r, p.action_ref));
    if (actual.phase != ActionTimeOwnerPhase::terminal)
      return RunStop::awaiting_permit;
    return finish(x_.state, p.action_ref)->success ? RunStop::completed
                                                   : RunStop::failed;
  });
}
